export const FORECASTING_SPECIFIC_CATALOG_WORKFLOW_COUNT = Object.keys(FORECASTING_SPECIFIC_WORKFLOWS).length;
export const hasForecastingSpecificCatalogWorkflow = (name: string): boolean => Boolean(FORECASTING_SPECIFIC_WORKFLOWS[name]);
export const forecastingSpecificCatalogWorkflow = (name: string): TechniqueStepDefinition[] | undefined => FORECASTING_SPECIFIC_WORKFLOWS[name]?.map((item) => ({ ...item }));
